mapper.update:

UPDATE LESSONS
SET LESSON_AT = #{lessonAt, jdbcType=TIMESTAMP}
WHERE ID = #{id}
	AND STUDENT_ID IN (
		SELECT S.ID
		FROM STUDENTS S
		WHERE S.INSTRUCTOR_ID = #{instructorId}
	)


UPDATE LESSONS
SET STATUS = #{status},
	STATUS_MEMO = #{statusMemo, jdbcType=VARCHAR}
WHERE ID = #{id}
	AND STUDENT_ID IN (
		SELECT S.ID
		FROM STUDENTS S
		WHERE S.INSTRUCTOR_ID = #{instructorId} 
	)
